import { getProjects, saveProjects } from "./storage";

export class Todo {
    constructor(title, dueDate) {
        this.title = title;
        this.dueDate = dueDate;
        this.complete = false;
        this.id = Date.now().toString();
    }

    toggleComplete() {
        this.complete = !this.complete;
    }
}

export class Project {
    constructor(name) {
        this.todos = [];
        this.name = name;
    }
    // Obtiene una tarea
    getTodo(id) {
        return this.todos.find(t => t.id === id);
    }

    // Agrega una tarea
    addTodo(todo) {
        this.todos.push(todo);
    }

    // Borra una tarea por ID
    deleteTodo(todoId) {
        this.todos = this.todos.filter(todo => todo.id !== todoId)
    }
}

export class Manager {
    constructor() {
        const loadedProjects = getProjects();

        if (Array.isArray(loadedProjects)) {
            // Reconstruimos la clase
            this.projects = loadedProjects.map(projData => {
                // Crea proyecto real
                const project = new Project(projData.name);

                // Llenamos con tareas reales
                project.todos = projData.todos.map(todoData => {
                    const todo = new Todo(todoData.title, todoData.dueDate);
                    // restauramos el estado y id
                    todo.complete = todoData.complete;
                    todo.id = todoData.id;
                    return todo;
                });
                return project;
            });
            this.currentProject = this.projects[0];
        } else {
            // Si no hay nada guardado, empezamos desde 0
            this.projects = [new Project("Inbox")];
            this.currentProject = this.projects[0];
        };
    };
}

export const todoManager = new Manager();