import { saveProjects } from "./storage";
import { Todo, todoManager } from "./todo";

export function renderTodos(project) {
    const listElement = document.querySelector('.task-list');
    listElement.innerHTML = ""; //Limpieza

    project.todos.forEach(todo => {
        const li = document.createElement('li');
        li.dataset.id = todo.id;
        li.innerHTML = `
            <input class="task-box" type="checkbox" ${todo.complete ? 'checked' : ''}>
            <span class="task">${todo.title}</span>
            <button class="delete-btn">
                <i class="fa-solid fa-trash"></i>
            </button>
        `;
        listElement.appendChild(li);
    });
}

export function setupEventListeners() {
    const dialog = document.querySelector('.task-dialog');
    const openBtn = document.querySelector('.add-task-btn');
    const closeBtn = document.querySelector('.btn-cancel');
    const form = document.querySelector('.task-dialog form');
    const taskList = document.querySelector('ul.task-list');

    taskList.addEventListener('click', (e) => {
        // Identifica el padre comun task row
        const li = e.target.closest('li');
        if (!li) return; // Ingora clicks fuera del LI

        const taskId = li.dataset.id;

        // CASO CHECKBOX
        if (e.target.type === 'checkbox') {
            const todo = todoManager.currentProject.getTodo(taskId);
            if (todo) {
                todo.toggleComplete();
                saveProjects(todoManager.projects);
            };
        };
        // CASO BORRAR
        if (e.target.closest('.delete-btn')) {
            todoManager.currentProject.deleteTodo(taskId);
            saveProjects(todoManager.projects)
            renderTodos(todoManager.currentProject)
        };
    });


    openBtn.addEventListener('click', (e) => {
        dialog.showModal()
    });

    closeBtn.addEventListener('click', () => {
        dialog.close();
        form.reset();
    });

    form.addEventListener('submit', (e) => {
        const titleInput = form.querySelector('input');
        const title = titleInput.value
        const newTodo = new Todo(title, "ayer");
        todoManager.currentProject.addTodo(newTodo);
        saveProjects(todoManager.projects);
        renderTodos(todoManager.currentProject);

        titleInput.value = '';
    });
}